px = im.load()
# find yellow pixels and white platen and dark spring
# print a coarse map
def classify(r,g,b):
    if r>180 and g>160 and b<80:
        return 'Y'  # yellow
    if r>200 and g>200 and b>200:
        return 'W'
    if r<40 and g<40 and b<40:
        return 'K'
    if 40<r<90 and 40<g<90 and 40<b<90:
        return 'D'  # dark gray spring?
    if r>80 and g>80 and b>80 and abs(r-g)<15 and abs(g-b)<15:
        return 'g'
    return '.'

# downsample
for y in range(0, h, 8):
    row = []
    for x in range(0, w, 4):
        row.append(classify(*px[x,y]))
    print(f"{y:3d} {''.join(row)}")
